<input class="w-full pl-10 pr-4 py-2.5 bg-surface-container-low text-on-surface rounded-lg font-body-md text-body-md placeholder:text-outline focus:outline-none focus:bg-surface-container-lowest shadow-inner" id="identifier" name="identifier" placeholder="000.000.000-00 ou nome@xinguara.pa.gov.br" type="text" value="482.903.112-84"/>
</div>
<p class="mt-1 font-body-sm text-body-sm text-on-surface-variant">Servidores municipais com domínio @xinguara.pa.gov.br</p>
