<!-- Light Interactive Script for Polish & State Feedback -->
<script>
  function togglePasswordVisibility() {
    const passInput = document.getElementById('passwordInput');
    const passIcon = document.getElementById('passIcon');
    if (!passInput || !passIcon) return;
    
    if (passInput.type === 'password') {
      passInput.type = 'text';
      passIcon.textContent = 'visibility_off';
    } else {
      passInput.type = 'password';
      passIcon.textContent = 'visibility';
    }
  }

  // Demonstration TOTP Timer countdown
  let countdownVal = 24;
  const countdownEl = document.getElementById('countdown');
  const timerCircle = document.getElementById('timerCircle');

  if (countdownEl && timerCircle) {
    setInterval(() => {
      countdownVal--;
      if (countdownVal < 0) {
        countdownVal = 30;
      }
      countdownEl.textContent = countdownVal + 's';
      const pct = (countdownVal / 30) * 100;
      timerCircle.setAttribute('stroke-dasharray', `${pct}, 100`);
    }, 1000);
  }

  function simulateProgress() {
    const btn = document.querySelector('button[type="submit"]');
    if (btn) {
      const originalText = btn.innerHTML;
      btn.innerHTML = '<span class="material-symbols-outlined animate-spin text-[18px]">progress_activity</span><span>Autenticando...</span>';
      btn.disabled = true;
      setTimeout(() => {
        btn.innerHTML = originalText;
        btn.disabled = false;
      }, 1200);
    }
  }

  function triggerSuccessDemo() {
    const btn = document.getElementById('btnVerify');
    if (btn) {
      btn.innerHTML = '<span class="material-symbols-outlined text-[20px]">check_circle</span><span>Sessão Autenticada com Sucesso</span>';
      btn.classList.remove('bg-secondary');
      btn.classList.add('bg-primary');
      setTimeout(() => {
        btn.innerHTML = '<span class="material-symbols-outlined text-[20px]" style="font-variation-settings: \'FILL\' 1;">task_alt</span><span>Validar e Iniciar Sessão</span>';
        btn.classList.remove('bg-primary');
        btn.classList.add('bg-secondary');
      }, 2500);
    }
  }
</script></main></body></html>